import Foundation
import CryptoKit
import Security
import SwiftUI

struct StudyAccount: Codable, Identifiable { var id = UUID(); var name: String; var platform: String; var entry: String }
struct StudyTask: Codable, Identifiable { var id = UUID(); var account: UUID; var title: String; var url: String; var kind: String; var state = "已暂停"; var position = 0.0; var duration = 0.0 }
struct StudyQuestion: Codable, Identifiable { var id: String; var account: UUID; var title: String; var type: String; var options: [String]; var answer: String; var canonical: String; var source: String; var explanation: String; var wrong = false }
struct Library: Codable { var accounts: [StudyAccount] = []; var tasks: [StudyTask] = []; var questions: [StudyQuestion] = []; var selected: [String:UUID] = [:]; var models: [String:String] = [:] }
enum StudyError: LocalizedError { case invalid(String); var errorDescription: String? { if case .invalid(let s) = self { return s }; return nil } }
@MainActor final class StudyStore: ObservableObject {
 @Published var library = Library(); @Published var platform = "chaoxing"; @Published var message = "独立运行，不需要电脑后台"
 let file: URL
 init() { file = URL.documentsDirectory.appending(path: "StudentTong/library.json"); if let data = try? Data(contentsOf:file) { do { library = try JSONDecoder().decode(Library.self,from:data) } catch { message = "资料读取失败，未覆盖原文件" } } }
 var account: StudyAccount? { library.accounts.first { $0.id == library.selected[platform] && $0.platform == platform } }
 func save() { do { try FileManager.default.createDirectory(at:file.deletingLastPathComponent(),withIntermediateDirectories:true); try JSONEncoder().encode(library).write(to:file,options:[.atomic,.completeFileProtection]) } catch { message = "资料保存失败：\(error.localizedDescription)" } }
 static func trusted(_ text:String,_ platform:String)->Bool { guard let u=URL(string:text),u.scheme=="https",u.user==nil,u.password==nil,u.port==nil,let h=u.host?.lowercased() else{return false}; return (platform=="chaoxing" ? ["chaoxing.com"]:["yuketang.cn","gdufemooc.cn"]).contains { h==$0 || h.hasSuffix("."+$0) } }
 func addAccount(_ name:String,_ entry:String)throws { guard !name.trimmingCharacters(in:.whitespaces).isEmpty,Self.trusted(entry,platform) else{throw StudyError.invalid("请输入账号名称和本平台HTTPS网址")};let a=StudyAccount(name:name,platform:platform,entry:entry);library.accounts.append(a);library.selected[platform]=a.id;save() }
 func select(_ a:StudyAccount){guard a.platform==platform else{return};library.selected[platform]=a.id;save()}
 func tasks(_ a:UUID)->[StudyTask]{library.tasks.filter{$0.account==a}}
 func questions(_ a:UUID,wrong:Bool=false)->[StudyQuestion]{library.questions.filter{$0.account==a && (!wrong || $0.wrong)}}
 func addTask(_ a:StudyAccount,title:String,url:String,kind:String)throws->UUID {guard Self.trusted(url,a.platform) else{throw StudyError.invalid("页面不属于当前平台")};let t=StudyTask(account:a.id,title:title,url:url,kind:kind);library.tasks.append(t);save();return t.id}
 func updateTask(_ id:UUID,_ a:UUID,state:String,position:Double,duration:Double){guard let i=library.tasks.firstIndex(where:{$0.id==id && $0.account==a})else{return};library.tasks[i].state=state;library.tasks[i].position=position;library.tasks[i].duration=duration;save()}
 func deleteTask(_ t:StudyTask,_ a:UUID){guard t.account==a,t.state != "进行中" else{message="请先停止任务";return};library.tasks.removeAll{$0.id==t.id && $0.account==a};save()}
 @discardableResult func collect(_ rows:[[String:Any]],_ a:UUID)->Int {var count=0;for q in rows{guard let title=q["title"] as? String,!title.isEmpty else{continue};let options=q["options"] as? [String] ?? [];let id=SHA256.hash(data:Data((a.uuidString+"|"+title+"|"+options.joined()).utf8)).map{String(format:"%02x",$0)}.joined();let official=q["platformAnswer"] as? String ?? "";let answer=official.isEmpty ? (q["referenceAnswer"] as? String ?? ""):official;let source=answer.isEmpty ? "尚无答案":official.isEmpty ? (q["referenceSource"] as? String ?? "参考答案"):"平台公布答案";let canonical=q[official.isEmpty ? "referenceCanonical":"canonicalAnswer"] as? String ?? Self.canonical(answer);var type=q["type"] as? String ?? "single";if q["needsVision"] as? Bool == true || (["single","multiple"].contains(type) && (options.isEmpty || options.count>26)){type="unknown"};var question=StudyQuestion(id:id,account:a,title:title,type:type,options:options,answer:answer,canonical:canonical,source:source,explanation:q["explanation"] as? String ?? "");if let i=library.questions.firstIndex(where:{$0.id==id && $0.account==a}){question.wrong=library.questions[i].wrong;if library.questions[i].source=="平台公布答案" && source != "平台公布答案"{question.answer=library.questions[i].answer;question.canonical=library.questions[i].canonical;question.source="平台公布答案"};library.questions[i]=question}else{library.questions.append(question)};count+=1};save();return count}
 static func canonical(_ s:String)->String {let value=s.uppercased().trimmingCharacters(in:.whitespacesAndNewlines);if ["对","正确","TRUE","√"].contains(value){return "TRUE"};if ["错","错误","FALSE","×"].contains(value){return "FALSE"};let clean=value.replacingOccurrences(of:"[\\s,，;；、]",with:"",options:.regularExpression);return clean.range(of:"^[A-Z]+$",options:.regularExpression) != nil ? String(clean.sorted()):clean}
 func check(_ q:StudyQuestion,_ a:UUID,_ answer:String)throws->Bool {guard q.account==a,let i=library.questions.firstIndex(where:{$0.id==q.id && $0.account==a}),!library.questions[i].answer.isEmpty else{throw StudyError.invalid("本题没有可判分答案")};let ok=Self.canonical(answer)==Self.canonical(library.questions[i].canonical);if !ok{library.questions[i].wrong=true;save()};return ok}
 func importData(_ data:Data,_ a:UUID)throws->Int {guard data.count<=16*1024*1024,let j=try JSONSerialization.jsonObject(with:data) as? [String:Any],let rows=j["questions"] as? [[String:Any]],rows.count<=20000 else{throw StudyError.invalid("题库格式错误或文件过大")};return collect(rows,a)}
 func exportData(_ a:UUID)throws->Data {let rows=questions(a).map{q->[String:Any] in var d:[String:Any]=["title":q.title,"type":q.type,"options":q.options,"explanation":q.explanation];d[q.source=="平台公布答案" ? "platformAnswer":"referenceAnswer"]=q.answer;d["referenceSource"]=q.source;d[q.source=="平台公布答案" ? "canonicalAnswer":"referenceCanonical"]=q.canonical;return d};return try JSONSerialization.data(withJSONObject:["schemaVersion":1,"questions":rows],options:[.prettyPrinted,.sortedKeys])}
}
enum StudySecrets {
 static func read(_ account:UUID)throws->String {let q:[String:Any]=[kSecClass as String:kSecClassGenericPassword,kSecAttrService as String:"com.studenttong.mobile.ai",kSecAttrAccount as String:account.uuidString,kSecReturnData as String:true];var value:CFTypeRef?;let status=SecItemCopyMatching(q as CFDictionary,&value);if status==errSecItemNotFound{return ""};guard status==errSecSuccess,let data=value as? Data,let text=String(data:data,encoding:.utf8)else{throw StudyError.invalid("密钥读取失败")};return text}
 static func save(_ key:String,_ account:UUID)throws {let q:[String:Any]=[kSecClass as String:kSecClassGenericPassword,kSecAttrService as String:"com.studenttong.mobile.ai",kSecAttrAccount as String:account.uuidString];SecItemDelete(q as CFDictionary);var item=q;item[kSecValueData as String]=Data(key.utf8);item[kSecAttrAccessible as String]=kSecAttrAccessibleWhenUnlockedThisDeviceOnly;guard SecItemAdd(item as CFDictionary,nil)==errSecSuccess else{throw StudyError.invalid("密钥保存失败")}}
}
